#!/usr/bin/env python3
"""Render the recorded results. No candidate computation or threshold fitting."""
import hashlib
import json
from pathlib import Path
from recover import HERE, ROOT

NAMES = {"17_tse": "#17 TSE feature proxy", "18_trees": "#18 Three Trees", "1_raster": "#1 Self-Teaching, raster", "1_html": "#1 Self-Teaching, HTML", "10_squint": "#10 Squint trajectory", "23_transport": "#23 Emphasis transport", "13_loom": "#13 Loom rank", "14_chord": "#14 Size chord", "27_band_17_tse": "#27 banded TSE", "27_band_1_raster": "#27 banded Self-Teaching", "27_band_10_squint": "#27 banded squint"}


def number(value):
    return "missing" if value is None else f"{value:.6f}"


def main():
    result = json.loads((HERE / "scores.json").read_text())
    corpus = json.loads((HERE / "corpus-measured.json").read_text())
    controls = json.loads((HERE / "controls.json").read_text())
    protocol = json.loads((HERE / "preregistration.json").read_text())
    frozen = json.loads((HERE / "freeze-serialization-fix.json").read_text())
    lines = ["# DPT wild-hunt verification: results", "", "**Screening complete. No tested implementation survived.** Seven named candidates were operationalized in eight score channels, followed by three pins-only banded retests (#27). All eleven score tests are **KILLED** under the frozen protocol. This rejects these specific measurements for instrument admission; it does not disprove TSE, information theory, optimal transport, or any other parent field.", "", "Manna: mn-c2d546. Report only. Production DPT, registry and `wild-hunt.md` are unchanged. No new dependency, public verb, scoring integration or commit. The issue remains claimed and in progress at the work order's explicit no-commit boundary.", "", "## What changes the decision", "", "1. **Do not put any survivor into DPT: there are none.** Three Trees has the strongest registered preference result, 8/10, but p=0.0546875 already misses alpha=0.05 before multiplicity correction (Holm p=0.6015625). Its worst canon-to-negative gap is only 0.001797 against the registered 0.05 margin. Its pin gate is incomplete because historic pin DOMs are absent.", "2. **Compression reuse is not enough.** Raster Self-Teaching gives broken 0.105452, above canon-today 0.027355 and canon-dossier 0.045960. The HTML channel gives barf 0.508021, above both canon fixtures. Its targeted raster ordering also fails: D1 0.028013 < B1 0.060646. The HTML channel orders that pair correctly, but fails both Null traps. The cross-round D1/B1 comparison has different capture lengths and is a supplemental falsifier only.", "3. **The TSE mapping needs conceptual repair before any new taste claim.** The tested feature-covariance proxy gives broken 3.137976, above both canons (1.907127 and 1.579979), and Pete's Pasta 1.740048. A plain white image scores 2.406769, also above both canons. Shared color/gradient descriptor structure creates apparent integration even in that blank image. A static descriptor covariance is not a neural dynamical ensemble. This result kills the implemented mapping, not the neuroscience formalism.", "4. **Bands can pass controls while failing taste.** The pins-only squint interval passes fixtures, both Null traps and all four available pins, but records only 1/10 strict preference wins. Most within-band specimens tie. This is why the human-feedback gate cannot be replaced by attractive fixture results.", "", "## Frozen gate results", "", "A = both liked-direction canon fixtures above both negative controls by the registered margin. B = all ten fixed preference pairs, one-sided binomial test with Holm correction across eleven tests. C = Null at/above the other four candidates' median in both surfaces. D = all four available pin screenshots above the negative-control band. I = incomplete, never a pass.", "", "| Implementation | A | B wins | Raw p | Holm p | C | D | Verdict |", "|---|---|---:|---:|---:|---|---|---|"]
    for name, g in result["gates"].items():
        lines.append(f"| {NAMES[name]} | {g['A']['status']} | {g['B']['wins']}/{g['B']['required_pairs']} | {number(g['B'].get('p_raw'))} | {number(g['B']['p_holm'])} | {g['C']['status']} | {g['D']['status']} | {g['status']} |")
    lines += ["", "No result sits in a pending BANDED-RETEST state: all three predeclared bands were actually run and failed. Candidates #2-9, #11-12, #15-16, #19-22, #24-26 and #28 remain **NOT TESTED**. The Reliquary was not revived.", "", "## Effect sizes and exact evidence", "", "Higher is better for every channel, including negative rank/roughness scores. Units differ; values must not be compared across rows. A positive gap below its predeclared margin still fails.", "", "| Implementation | Canon Today | Canon Dossier | Barf | Broken | Worst fixture gap | Required margin |", "|---|---:|---:|---:|---:|---:|---:|"]
    for name, g in result["gates"].items():
        v = g["A"]["values"]
        nums = [v[k] for k in ["fixtures/canon-today", "fixtures/canon-dossier", "fixtures/barf", "fixtures/broken"]]
        lines.append("| " + NAMES[name] + " | " + " | ".join(number(x) for x in nums + [g["A"].get("gap"), g["A"]["margin"]]) + " |")
    lines += ["", "Each raw score's `details` includes its measurement components: TSE subset-size curve, the three MI agreements, all three compressed sizes, blur divergences, transport distributions, effective rank or chord counts. `scores.json` includes every pair's exact gap, success flag, label role, round, confidence interval and required denominator.", "", "### Round and label census", "", f"{result['total_specimens']} specimens indexed. {result['eligible_specimens']} retained for evaluation: 68 have image evidence, and 64 have reconstructed HTML plus a current renderer DOM probe. Pin 002 is still an explicit missing specimen. Eleven specimens are excluded from scoring: three disputed Round 7 candidates, six unruled reground candidates, and two Engine Round 4 refinements without an exact bound specimen-level ruling.", "", "| Corpus group | Indexed | Human-label handling |", "|---|---:|---|"]
    notes = {"concept": "today-C and dossier-D winners; other siblings unselected, not invented kills", "concept2": "both complete trap sets; Library Null compared to two explicit rejections", "lib3": "paneldock provisional winner vs four explicit rejections", "lib4": "askhero winner; other siblings unnoted", "eng3": "oneline and timetable2 advanced vs ledgerfirst rejected", "eng4": "two refinements retained outside scoring", "eng5": "all 14 candidates; no declared winner, hence no manufactured winning pairs", "eng6": "M1 advanced and D1 conditional winner vs MC1's rejected arrangement; silent entries not negative votes", "eng7": "E2 chat / E3 page conflict; excluded", "reground": "A/B/C Today and Engine; no recovered final ruling, excluded", "fixtures": "two liked-direction fixtures plus barf/broken controls", "pins": "five declared; four screenshots, no matched historic DOMs"}
    for group in ["concept", "concept2", "lib3", "lib4", "eng3", "eng4", "eng5", "eng6", "eng7", "reground", "fixtures", "pins"]:
        lines.append(f"| {group} | {sum(r['round'] == group for r in corpus['specimens'])} | {notes[group]} |")
    lines += ["", "The ten primary pairs span four feedback groups. They compare advancement/preference against explicit rejection of a design or arrangement; they are not ten independent unconditional final-winner decisions. The same preferred page appears in multiple pairs. Therefore the nominal binomial p-values are screening diagnostics, not population inference. The fixed comparison list and exact quotes are in PROTOCOL.md, corpus.json and each round's labels.yaml.", "", "| Implementation | Concept 2 | Library 3 | Engine 3 | Engine 6 | Without provisional/conditional choices | Round sign-flip p |", "|---|---:|---:|---:|---:|---:|---:|"]
    for name, g in result["gates"].items():
        b = g["B"]
        cols = [f"{b['by_round'][r]['wins']}/{b['by_round'][r]['pairs']}" for r in ["concept2", "lib3", "eng3", "eng6"]]
        nc = b["nonconditional"]
        lines.append(f"| {NAMES[name]} | " + " | ".join(cols) + f" | {nc['wins']}/{nc['pairs']} | {number(b['round_sign_flip_p'])} |")
    lines += ["", "With four groups the sign-flip diagnostic has only 16 assignments and limited resolution. The 5/5 nonconditional Three Trees subset was predeclared for disclosure, not for replacing the ten-pair test after seeing outcomes.", "", "### Trap gaps", "", "Null score minus the other four designs' median. Both surface gaps must be nonnegative. A trap failure rejects the proxy; it does not identify novelty bias as a proven psychological cause.", "", "| Implementation | Library gap | Engine gap |", "|---|---:|---:|"]
    for name, g in result["gates"].items():
        lines.append(f"| {NAMES[name]} | " + " | ".join(number(t.get("gap")) for t in g["C"]["surfaces"]) + " |")
    lines += ["", "### Pins-only bands", "", "| Base measurement | Low | High | Negative controls inside interval |", "|---|---:|---:|---|"]
    for name, band in result["bands"].items():
        base = name.removeprefix("27_band_")
        inside = [control for control in ["barf", "broken"] if band["low"] <= result["scores"]["fixtures/" + control][base]["score"] <= band["high"]]
        lines.append(f"| {NAMES[base]} | {number(band['low'])} | {number(band['high'])} | {', '.join(inside) or 'neither'} |")
    lines += ["", "TSE's pin interval contains both negative controls; Self-Teaching's contains barf. Their register gate cannot separate those controls. Squint excludes both controls but largely flattens the real design comparisons into ties. All band parameters came only from the four pins. Pin passage for a pins-fitted band is calibration, not independent validation.", "", "### TSE limiting-case diagnostics", "", "| Constructed raster | Score |", "|---|---:|"]
    for name, r in controls["scores"].items():
        lines.append(f"| {name} | {number(r['score'])} |")
    lines += ["", "These controls expose how the specific descriptor ensemble behaves, including shared channel/gradient structure. They were predeclared diagnostics and did not alter any score, threshold or label. The mathematical correlation identity control is exactly zero; the moderate block-correlated control is 0.497034 and the near-cloned-variable control is 2.406769. Do not transfer a neural-complexity interpretation to this image proxy.", "", "## Provenance and limitations", "", "- Recovered 261 source/asset versions from 141 transcript files, plus seven complete saved artifact galleries. Every source version has a hash and transcript/tool-result receipt in recovery.json. No recorded shell command was executed. Successful Write/Edit replay was exact; zero edits required guessing.", "- Gallery image bytes supersede transcript thumbnails. M3's gallery image differs from its Read image; the gallery version was selected before scoring. One nominal .png Read carried JPEG bytes, which remain correctly typed and attributed.", "- Auction Lot is dossier-D, verified from the original gallery title/IMG placeholder and blind key, not from a recap. Library Round 3's paneldock preference and Library Round 4's askhero win remain distinct. Round 7's conflict remains unresolved.", "- Early round captures are 1440x900 viewports. Round 6 consists of full-page 1920-wide captures of different lengths. Pins are still longer full pages. The 360-pixel analysis width preserves aspect ratio but cannot remove content-length or capture-policy confounds. The 24-region TSE partition stretches across each whole capture.", "- DOM measurements are fresh probes of recovered HTML, clipped to historical image extent. They are not verified pixel-identical historical browser states. Unused font subsets can remain unloaded; no font load errors or broken image loads were observed in the 64 probes. No historical DOM exists for the pin captures. No current live page was quietly substituted.", "- DOM containment is not semantic truth. Minimum partition agreement does not know whether MC1's connectors represent real flow; area/heading weights do not know business importance. The implementations test declared proxies only.", "- The corpus is one person's selected examples, not an independent aesthetic population. There is no learned aesthetic judge, no holdout claim for the pin-fitted bands, no manufactured uncertainty band, and no adjustment after scores.", "", "## Verification and reproduction", "", "Ten analytic/regression checks passed: independence and modular integration, finite constant-raster output, partition identity/independence, compression prefix behavior, missing-evidence refusal, tie/denominator handling, multiplicity family retention, browse close's text contract, and JSON scalar/NaN handling. 237 frozen input/code files and all protected paths verified after the successful run. A full replay from those frozen inputs exactly reproduced every score, component detail, gate, band and TSE diagnostic (verification.json). No production source changed; the repository-wide test.sh suite was not run for this isolated research artifact.", "", "The initial full run failed at JSON serialization of a NumPy integer before writing or inspecting score values. The original freeze is retained. AMENDMENT-serialization.md and serialization-amendment.json identify the three changed files: JSON boundary, freeze-record selection/console count, and the regression test. metrics.py, PROTOCOL.md, config.json, labels and input evidence hashes were unchanged. The second immutable seal preceded the successful rerun.", "", f"- Protocol registration UTC: `{protocol['created_utc']}`", f"- Corrected run freeze UTC: `{frozen['frozen_utc']}`", f"- Results UTC: `{result['created_utc']}`", f"- Protocol SHA-256: `{hashlib.sha256((HERE / 'PROTOCOL.md').read_bytes()).hexdigest()}`", f"- Scores SHA-256: `{hashlib.sha256((HERE / 'scores.json').read_bytes()).hexdigest()}`", f"- Runtime: Python {result['environment']['python'].split()[0]}, NumPy {result['environment']['numpy']}, SciPy {result['environment']['scipy']}, Pillow {result['environment']['pillow']}, Zstd 1.5.7, macOS arm64.", "", "From the repo root, using the existing scientific Python installation:", "", "```bash", "OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 /opt/homebrew/bin/python3.10 corpus/design-research/wildhunt-verify/test_research.py", "OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 /opt/homebrew/bin/python3.10 corpus/design-research/wildhunt-verify/evaluate.py --verify --freeze-record /Users/erik/Custom-Coding/agent-do/corpus/design-research/wildhunt-verify/freeze-serialization-fix.json", "```", "", "To recompute without replacing the recorded results, pass the same freeze record plus `--out` pointing to a new file under `.dev/dpt-wildhunt/`. All observed inputs, settings and component values accompany the report. Capture regeneration uses capture.py through agent-do browse and creates a new observational state; do not overwrite the frozen probes for a replication.", "", "Mathematical source receipts and operational definitions are in [PROTOCOL.md](PROTOCOL.md), including [TSE's original paper](https://pubmed.ncbi.nlm.nih.gov/8197179/), [Gaussian neural complexity analysis](https://arxiv.org/abs/1011.5334), [Meila's partition-comparison paper](https://sites.stat.washington.edu/mmp/Papers/icml05-compare-axioms.pdf), [Zstandard](https://facebook.github.io/zstd/zstd_manual.html), and [Hou/Zhang spectral residual saliency](https://bcmi.sjtu.edu.cn/home/zhangliqing/Papers/2007CVPR_Houxiaodi_04270292.pdf). These sources establish the underlying methods, not that the proposed aesthetic applications work.", "", "## Completion boundary", "", "The authorized screening and report are complete. No surviving position is entered into ZPC, and no candidate is admitted to DPT. Lessons logged: 11 (new) | Decisions logged: 0 (new). Eight instructive candidate/banding failures and three recovery/export lessons are recorded in ledger-receipts.json and the project ledger. The Manna claim is retained until Erik's explicit commit instruction, as required by this work order. Remaining generation candidates and any revised operationalizations are optional future research, not unfinished requirements for this screening wave.", "", "**TL;DR (12th grade):** The evidence was recovered and the first seven proposed measures were tested under rules written before scoring. None qualified. Three Trees tracked some of your preferences but missed its pass requirements; compression and several other formulas rewarded rejected designs. Pins-only bands could pass simple controls while missing actual design choices. Keep DPT unchanged and treat this as evidence against these implementations, not a verdict on all possible mathematics of taste.", ""]
    (HERE / "RESULTS.md").write_text("\n".join(lines))
    print("Wrote", HERE / "RESULTS.md", "lines", len(lines))


if __name__ == "__main__":
    main()
